import 'package:flutter/material.dart';
import 'package:flutter_svg/flutter_svg.dart';

import 'paynow_color.dart';

/// Vector asset generator for Singapore PayNow payment branding.
class PayNowAssets {
  PayNowAssets._();

  /// Renders the official full PayNow wordmark logo.
  static Widget logo({required PayNowColor color, double height = 24.0}) {
    final String logoColor =
        color == PayNowColor.white ? '#7D1978' : '#FFFFFF';

    return SvgPicture.string(
      _payNowLogoSvg(logoColor: logoColor),
      height: height,
      fit: BoxFit.contain,
    );
  }

  /// Renders the standalone PayNow monogram emblem.
  static Widget emblem({required PayNowColor color, double height = 24.0}) {
    final String badgeBg = color == PayNowColor.white
        ? '#7D1978'
        : (color == PayNowColor.magenta ? '#ED0080' : '#7D1978');
    final String glyphColor = '#FFFFFF';

    return SvgPicture.string(
      _payNowEmblemSvg(badgeBg: badgeBg, glyphColor: glyphColor),
      height: height,
      fit: BoxFit.contain,
    );
  }

  static String _payNowEmblemSvg({
    required String badgeBg,
    required String glyphColor,
  }) {
    return '''
<svg viewBox="0 0 44 44" fill="none" xmlns="http://www.w3.org/2000/svg">
  <rect width="44" height="44" rx="9" fill="$badgeBg"/>
  <g transform="translate(6, 4) scale(0.68)" fill="$glyphColor" fill-rule="evenodd">
    <path d="M 3 5 L 24 5 L 24 6 L 28 6 L 28 7 L 30 7 L 30 8 L 33 10 L 33 12 L 35 13 L 35 16 L 36 16 L 36 23 L 35 23 L 35 26 L 34 26 L 34 28 L 33 28 L 33 29 L 32 29 L 29 33 L 26 33 L 26 34 L 13 34 L 13 50 L 3 50 L 3 49 L 2 49 L 2 6 L 3 6 Z M 15 14 L 13 15 L 13 25 L 22 25 L 22 24 L 24 24 L 24 22 L 25 22 L 25 18 L 24 18 L 24 16 L 23 16 L 23 15 L 20 15 L 20 14 Z"/>
    <path d="M 38 34 L 46 34 L 46 37 L 42 41 L 46 41 L 46 50 L 36 50 L 36 47 L 40 43 L 36 43 Z"/>
  </g>
</svg>
''';
  }

